using System;using System.IO;using UnityEditor;using UnityEditor.Build.Reporting;using UnityEngine;
namespace IdleIntelligence.Editor {public static class BuildLocalPlayer {
 public static void Build(){string output=Environment.GetEnvironmentVariable("IDLE_PLAYER_OUTPUT")??"/tmp/IdleIntelligence-local.app";if(Directory.Exists(output))throw new InvalidOperationException("Choose a new local player output");var report=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=CreateBootScene.PlayerScenes,locationPathName=output,target=BuildTarget.StandaloneOSX,options=BuildOptions.Development|BuildOptions.StrictMode});Debug.Log("LOCAL_PLAYER_BUILD "+report.summary.result+" platform="+report.summary.platform+" bytes="+report.summary.totalSize+" errors="+report.summary.totalErrors);if(report.summary.result!=BuildResult.Succeeded)throw new Exception("Local player build failed");File.WriteAllText(output+".report.txt",report.summary.result+"\n"+report.summary.platform+"\n"+report.summary.totalSize+" bytes\n"+report.summary.totalTime);}
}}
